import subprocess, json, glob, os
def run(seed, w, h, nbots=1, extra=()):
    for f in glob.glob('*.hlt'): os.remove(f)
    cmd = ['./executable','-t','-q','-s',str(seed),'-d',f'{w} {h}'] + list(extra) + ['python3 tests/passive.py']*nbots
    p = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
    fs = glob.glob('*.hlt')
    if not fs: return None, p
    j = json.load(open(fs[0])); os.remove(fs[0])
    return j, p

print("n=6 10x10 various seeds:")
for seed in range(1,8):
    j,p = run(seed,10,10,nbots=6)
    if j is None: print(' seed',seed,'FAIL out=',repr(p.stdout[:300]),'err=',repr(p.stderr[:120]))
