cd /workspace/work/sim && cat > probe.py <<'EOF'
import sys, os
from harness import run, starts
HERE = os.path.dirname(os.path.abspath(__file__))
def game(seed, w, h, scripts, extra=(), keep=False, names=None):
    bots = []
    for i, s in enumerate(scripts):
        if s is None:
            bots.append('python3 passive.py')
        else:
            sf = os.path.join(HERE, f'script_{i}.txt')
            with open(sf, 'w') as f: f.write(s)
            nm = names[i] if names else f'Bot{i}'
            bots.append(f'python3 scripted.py {sf} /dev/null {nm}')
    return run(seed=seed, w=w, h=h, bots=bots, extra=extra, keep=keep)
def owned(j, t, pl=None):
    F = j['frames'][t]; W, H = j['width'], j['height']
    out = {}
    for y in range(H):
        for x in range(W):
            c = F[y][x]
            if c[0] != 0 and (pl is None or c[0] == pl):
                out[(x, y)] = tuple(c)
    return out
def cell(j, t, x, y):
    return tuple(j['frames'][t][y][x])
