cd /workspace/work/rng && python3 - <<'EOF'
import json, math
data = json.load(open('onebyone.json'))
seeds = sorted(int(s) for s in data)
prods = [data[str(s)][0] for s in seeds]
strs  = [data[str(s)][1] for s in seeds]

# parse prng seqs
blocks = {}
cur = None
for line in open('prng_seqs.txt'):
    line = line.strip()
    if line.startswith('=='):
        cur = line.strip('= ').strip()
        blocks[cur] = {}
    elif line and ':' in line:
        s, rest = line.split(':',1)
        blocks[cur][int(s)] = [float(x) for x in rest.split()]

def check(name, vals, target, label):
    # vals: list of sequences per seed
    hits = []
    for idx in range(len(vals[0])):
        col = [v[idx] for v in vals]
        # try floor(v * M), floor(v*M)+a, round(v*M)
        for M in list(range(2, 300)) + [255,256,1000,2**31,2**32]:
            if all(int(c*M) == t for c,t in zip(col,target)):
                hits.append((idx,'floor*',M))
        # try mod for raw ints
        if max(col) > 10:
            for M in range(2, 300):
                if all(int(c)%M == t for c,t in zip(col,target)):
                    hits.append((idx,'mod',M))
    if hits:
        print(name, label, hits[:5])

for name, d in blocks.items():
    vals = [d[s] for s in seeds]
    isfloat = '.' in open('prng_seqs.txt').read().split('== '+name+' ==')[1].split('\n')[1]
    check(name, vals, strs, 'strength')
    check(name, vals, prods, 'prod')
print("done")
EOF

