args.content:
import json

data = json.load(open('onebyone.json'))
seeds = sorted(int(s) for s in data)
strs = [float(data[str(s)][1]) for s in seeds]
prods = [float(data[str(s)][0]) for s in seeds]

blocks = {}; cur = None
for line in open('prng_seqs.txt'):
    line = line.strip()
    if line.startswith('=='): cur = line.strip('= ').strip(); blocks[cur] = {}
    elif ':' in line:
        s, rest = line.split(':', 1); blocks[cur][int(s)] = [float(x) for x in rest.split()]

def solve(A, b):
    n = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]
    for c in range(n):
        p = max(range(c, n), key=lambda r: abs(M[r][c]))
        if abs(M[p][c]) < 1e-12: return None
        M[c], M[p] = M[p], M[c]
        for r in range(n):
            if r != c and M[r][c] != 0:
                f = M[r][c] / M[c][c]
                for k in range(c, n+1): M[r][k] -= f * M[c][k]
    return [M[i][n] / M[i][i] for i in range(n)]

def lstsq(X, y):
    n = len(X[0])
    A = [[sum(row[i]*row[j] for row in X) for j in range(n)] for i in range(n)]
    b = [sum(row[i]*v for row, v in zip(X, y)) for i in range(n)]
    coef = solve(A, b)
    if coef is None: return None, 1e9
    err = max(abs(sum(c*x for c, x in zip(coef, row)) - v) for row, v in zip(X, y))
    return coef, err

for name in blocks:
    if not name.endswith('-ud'): continue
    d = blocks[name]
    for K in [1, 2, 3, 4, 6, 8]:
        X = [[1.0] + d[s][:K] for s in seeds]
        for tgt, lab in [(strs, 'str'), (prods, 'prod')]:
            coef, err = lstsq(X, tgt)
            if err < 0.5: print("HIT", name, K, lab, coef)
            elif err < 3: print("close", name, K, lab, round(err,3), [round(c,3) for c in coef])
print("scan done")

