#include <random>
#include <cstdio>
#include <cstdlib>
using namespace std;
template<class E> void dumpd(const char* name, int nseeds, int nvals) {
    printf("== %s-ud ==\n", name);
    for (int s = 1; s <= nseeds; s++) {
        E e(s);
        uniform_real_distribution<double> d(0.0, 1.0);
        printf("%d:", s);
        for (int i = 0; i < nvals; i++) printf(" %.9f", d(e));
        printf("\n");
    }
}
int main() {
    dumpd<mt19937>("mt19937", 100, 64);
    dumpd<mt19937_64>("mt19937_64", 100, 64);
    dumpd<minstd_rand>("minstd_rand", 100, 64);
    dumpd<minstd_rand0>("minstd_rand0", 100, 64);
    dumpd<ranlux24_base>("ranlux24_base", 100, 64);
    dumpd<knuth_b>("knuth_b", 100, 64);
    printf("== rand-ud ==\n");
    for (int s = 1; s <= 100; s++) {
        srand(s); printf("%d:", s);
        for (int i = 0; i < 64; i++) printf(" %.9f", rand() / (RAND_MAX + 1.0));
        printf("\n");
    }
    return 0;
}
