cd /workspace/work/main/rngtest && cat > fit1.c <<'EOF'
#include <stdio.h>
#include <stdint.h>
#include <math.h>
#include <random>
// 1x1 observed: seeds 1..20 -> prod, str
int P[20]={7,8,6,15,8,13,13,12,13,13,7,15,12,8,10,10,14,12,8,9};
int S[20]={199,155,231,156,183,242,165,155,210,248,164,221,239,192,247,229,241,186,202,156};
int main(){
    // generate mt float streams (raw/2^32) for seeds 1..20, 64 values each
    static double u[21][64];
    for(int s=1;s<=20;s++){
        std::mt19937 mt(s);
        for(int i=0;i<64;i++) u[s][i]=mt()/4294967296.0;
    }
    // single-value formulas
    for(int k=0;k<60;k++){
        int okS=1,okP=1;
        for(int s=1;s<=20;s++){
            if((int)floor(256*u[s][k])!=S[s-1]) okS=0;
            if((int)floor(16*u[s][k])!=P[s-1]) okP=0;
        }
        if(okS)printf("S = floor(256*u[%d])\n",k);
        if(okP)printf("P = floor(16*u[%d])\n",k);
    }
    // two-value means
    for(int a=0;a<32;a++)for(int b=a+1;b<32;b++){
        int okS=1;
        for(int s=1;s<=20;s++){
            if((int)floor(256*(u[s][a]+u[s][b])/2)!=S[s-1]){okS=0;break;}
        }
        if(okS)printf("S = floor(256*mean(u[%d],u[%d]))\n",a,b);
    }
    // means of K consecutive starting at k
    for(int k=0;k<32;k++)for(int K=2;K<=8;K++){
        int okS=1,okP=1;
        for(int s=1;s<=20;s++){
            double m=0; for(int i=0;i<K;i++)m+=u[s][k+i]; m/=K;
            if((int)floor(256*m)!=S[s-1])okS=0;
            if((int)floor(16*m)!=P[s-1])okP=0;
            if(!okS&&!okP)break;
        }
        if(okS)printf("S = floor(256*mean(u[%d..%d]))\n",k,k+K-1);
        if(okP)printf("P = floor(16*mean(u[%d..%d]))\n",k,k+K-1);
    }
    printf("done\n");
}
EOF
