#include <stdio.h>
#include <math.h>
#include <random>
int P[20]={7,8,6,15,8,13,13,12,13,13,7,15,12,8,10,10,14,12,8,9};
int S[20]={199,155,231,156,183,242,165,155,210,248,164,221,239,192,247,229,241,186,202,156};
static double u[20][256];
double corrsum(int off,int stride,int K,int*obs){
    double xs[20],ys[20],mx=0,my=0,num=0,dx=0,dy=0;
    for(int s=0;s<20;s++){
        double t=0;for(int i=0;i<K;i++)t+=u[s][off+i*stride];
        xs[s]=t;ys[s]=obs[s];mx+=t;my+=ys[s];
    }
    mx/=20;my/=20;
    for(int s=0;s<20;s++){num+=(xs[s]-mx)*(ys[s]-my);dx+=(xs[s]-mx)*(xs[s]-mx);dy+=(ys[s]-my)*(ys[s]-my);}
    return num/sqrt(dx*dy);
}
int main(){
    for(int s=1;s<=20;s++){std::mt19937 mt(s);for(int i=0;i<256;i++)u[s-1][i]=mt()/4294967296.0;}
    double best=0;int bo=0,bs=1,bk=0,bw=0;
    for(int stride=1;stride<=6;stride++)
      for(int off=0;off<stride*3;off++)
        for(int K=2;K<=60;K++){
            if(off+(K-1)*stride>=256)break;
            double c=corrsum(off,stride,K,S);
            if(fabs(c)>fabs(best)){best=c;bo=off;bs=stride;bk=K;bw=0;}
            double c2=corrsum(off,stride,K,P);
            if(fabs(c2)>fabs(best)){best=c2;bo=off;bs=stride;bk=K;bw=1;}
        }
    printf("best corr %.4f at off=%d stride=%d K=%d target=%s\n",best,bo,bs,bk,bw?"P":"S");
}
EOF
