#include <stdio.h>
#include <math.h>
#include <random>
// 1x1 observed S for seeds 1..20
int S[20]={199,155,231,156,183,242,165,155,210,248,164,221,239,192,247,229,241,186,202,156};
// Hypothesis: K blobs. Draw order per blob: either (amp,pos,pos)=stride3 amp-first, or (pos,pos,amp) amp-last.
// amp transform: u, u*u, sqrt(u). combine: max or sum. final: floor(255*f), round(255*f), floor(256*f).
// K: fixed, or K = kmin + floor(u0*(kmax-kmin+1)).
int main(){
    for(int s=1;s<=20;s++){
    }
    // brute force
    double bestCorr=0; char bestDesc[256]; int bestMatch=0; char bestMD[256];
    for(int ampfirst=0;ampfirst<2;ampfirst++)
    for(int tr=0;tr<3;tr++)
    for(int comb=0;comb<2;comb++)
    for(int fin=0;fin<3;fin++)
    for(int Kmode=0;Kmode<3;Kmode++) // 0: fixed K, 1: K=1+floor(u0*K), 2: K=1+floor(u0*K/2)...
    for(int K=1;K<=40;K++){
        int match=0; double xs[20],ys[20];
        for(int s=1;s<=20;s++){
            std::mt19937 mt(s);
            std::uniform_real_distribution<double> U(0,1);
            int k = K;
            double u0 = U(mt);
            if(Kmode==1) k = 1 + (int)floor(u0*K);
            if(Kmode==2) k = 1 + (int)floor(u0*K*0.5);
            if(Kmode==0) { /* use u0 consumed anyway? try not consuming: redo */ }
            // variant: for Kmode==0, don't consume u0
            std::mt19937 mt2(s);
            std::mt19937* mgp = (Kmode==0)? (std::mt19937*)&mt2 : (std::mt19937*)&mt;
            std::mt19937& mg = *mgp;
            double acc = (comb==0)?0.0:0.0; // max: start 0; sum: start 0
            for(int i=0;i<k;i++){
                double a;
                if(ampfirst){ a=U(mg); U(mg); U(mg); }
                else { U(mg); U(mg); a=U(mg); }
                if(tr==1) a=a*a;
                if(tr==2) a=sqrt(a);
                if(comb==0){ if(a>acc)acc=a; } else acc+=a;
            }
            int v;
            if(fin==0) v=(int)floor(255*acc);
            else if(fin==1) v=(int)floor(256*acc);
            else v=(int)lround(255*acc);
            if(v==S[s-1]) match++;
            xs[s-1]=acc; ys[s-1]=S[s-1];
        }
        double mx=0,my=0,num=0,dx=0,dy=0;
        for(int i=0;i<20;i++){mx+=xs[i];my+=ys[i];}mx/=20;my/=20;
        for(int i=0;i<20;i++){num+=(xs[i]-mx)*(ys[i]-my);dx+=(xs[i]-mx)*(xs[i]-mx);dy+=(ys[i]-my)*(ys[i]-my);}
        double c=num/sqrt(dx*dy+1e-12);
        if(match>bestMatch){bestMatch=match;snprintf(bestMD,256,"ampfirst=%d tr=%d comb=%d fin=%d Kmode=%d K=%d",ampfirst,tr,comb,fin,Kmode,K);}
        if(fabs(c)>fabs(bestCorr)){bestCorr=c;snprintf(bestDesc,256,"ampfirst=%d tr=%d comb=%d fin=%d Kmode=%d K=%d",ampfirst,tr,comb,fin,Kmode,K);}
    }
    printf("best match %d/20: %s\n",bestMatch,bestMD);
    printf("best corr %.3f: %s\n",bestCorr,bestDesc);
}
EOF
