    const int NS=100, NV=300;
    // mt19937 + normal_distribution
    {
        printf("== mt19937-norm ==\n");
        for (int s=1;s<=NS;s++){ mt19937 e(s); normal_distribution<double> d(0,1);
            printf("%d:",s); for(int i=0;i<NV;i++) printf(" %.6f", d(e)); printf("\n"); }
    }
    // mt19937 seeded via seed_seq
    {
        printf("== mt19937ss-ud ==\n");
        for (int s=1;s<=NS;s++){ seed_seq sq{(unsigned)s}; mt19937 e(sq); uniform_real_distribution<double> d(0,1);
            printf("%d:",s); for(int i=0;i<NV;i++) printf(" %.9f", d(e)); printf("\n"); }
    }
    {
        printf("== mt19937ss-norm ==\n");
        for (int s=1;s<=NS;s++){ seed_seq sq{(unsigned)s}; mt19937 e(sq); normal_distribution<double> d(0,1);
            printf("%d:",s); for(int i=0;i<NV;i++) printf(" %.6f", d(e)); printf("\n"); }
    }
    // mt19937 deep uniform
    {
        printf("== mt19937-ud-deep ==\n");
        for (int s=1;s<=NS;s++){ mt19937 e(s); uniform_real_distribution<double> d(0,1);
            printf("%d:",s); for(int i=0;i<NV;i++) printf(" %.9f", d(e)); printf("\n"); }
